public long substrCount(int n, String s) {
    long count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (isSpecial(s, i, j)) count++;
        }
    }
    return count;
}

private boolean isSpecial(String s, int i, int j) {
    int len = j - i + 1;
    char first = s.charAt(i);
    boolean allSame = true;
    for (int k = i; k <= j; k++) {
        if (s.charAt(k) != first) { allSame = false; break; }
    }
    if (allSame) return true;
    if (len % 2 == 0) return false;
    int mid = (i + j) / 2;
    for (int k = i; k <= j; k++) {
        if (k != mid && s.charAt(k) != first) return false;
    }
    return true;
}

