def substr_count(self, n: int, s: str) -> int:
    def is_special(i: int, j: int) -> bool:
        first = s[i]
        if all(s[k] == first for k in range(i, j + 1)):
            return True
        length = j - i + 1
        if length % 2 == 0:
            return False
        mid = (i + j) // 2
        return all(s[k] == first for k in range(i, j + 1) if k != mid)

    count = 0
    for i in range(n):
        for j in range(i, n):
            if is_special(i, j):
                count += 1
    return count

