public long substrCount(int n, String s) {
    List<int[]> runs = new ArrayList<>();
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && s.charAt(j) == s.charAt(i)) j++;
        runs.add(new int[]{s.charAt(i), j - i});
        i = j;
    }
    long total = 0;
    for (int[] run : runs) {
        long len = run[1];
        total += len * (len + 1) / 2;
    }
    for (int k = 1; k + 1 < runs.size(); k++) {
        if (runs.get(k)[1] == 1 && runs.get(k - 1)[0] == runs.get(k + 1)[0]) {
            total += Math.min(runs.get(k - 1)[1], runs.get(k + 1)[1]);
        }
    }
    return total;
}

