def substr_count(self, n: int, s: str) -> int:
    runs = []
    for c in s:
        if runs and runs[-1][0] == c:
            runs[-1][1] += 1
        else:
            runs.append([c, 1])
    total = 0
    for _, length in runs:
        total += length * (length + 1) // 2
    for k in range(1, len(runs) - 1):
        if runs[k][1] == 1 and runs[k - 1][0] == runs[k + 1][0]:
            total += min(runs[k - 1][1], runs[k + 1][1])
    return total
